def solve_game_type(N):
    # DP[n] = True if n is a P-position (losing for current player, Type B move), False if N-position (winning, Type A move)
    # We only care about n < N
    dp = {} 

    # Since the player who writes N wins, any position n such that n+1=N or 2n=N is an N-position (False)

    for n in range(N - 1, 0, -1):
        can_move_to_P = False

        # Check move n+1
        if n + 1 == N:
            # Immediate win (N-position)
            dp[n] = False
            continue

        if n + 1 in dp and dp[n+1] == True:
            # Moving to a P-position means n is an N-position
            can_move_to_P = True

        # Check move 2n
        if 2 * n <= N:
            if 2 * n == N:
                # Immediate win (N-position)
                dp[n] = False
                continue

            if 2 * n in dp and dp[2*n] == True:
                # Moving to a P-position means n is an N-position
                can_move_to_P = True

        if can_move_to_P:
            dp[n] = False # N-position
        else:
            dp[n] = True  # P-position

    # N is Type B if the starting position 1 is a P-position (dp[1] == True)
    return dp.get(1)

