def solve_game_type(N):
    # W[n] = True if n is an N-position (Winning), False if P-position (Losing)
    # We only need to calculate up to N-1
    W = [False] * (N + 1)

    # Iterate backward from N-1 down to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move n+1
        if n + 1 <= N:
            # If moving to n+1 results in a P-position (Losing for opponent), then n is N-position
            # Note: If n+1 == N, the player wins immediately, which is equivalent to moving to a P-position for the opponent.
            if n + 1 == N or not W[n + 1]:
                can_win = True

        # Check move 2n
        if not can_win and 2 * n <= N:
            # If moving to 2n results in a P-position (Losing for opponent), then n is N-position
            if 2 * n == N or not W[2 * n]:
                can_win = True

        W[n] = can_win

    # Type A if W[1] is True (N-position), Type B if W[1] is False (P-position)
    if W[1]:
        return "Type A"
    else:
        return "Type B"

